import{_ as e,o as a,c as l,ah as s}from"./chunks/framework.CPHJ30oF.js";const o=JSON.parse('{"title":"02-零基础Docker极速入门-10分钟跑起你的第一个Nginx容器","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"为什么先从 Nginx 开始？","slug":"为什么先从-nginx-开始","link":"#为什么先从-nginx-开始","children":[]},{"level":2,"title":"关键流程：拉镜像、启动容器、访问服务","slug":"关键流程-拉镜像、启动容器、访问服务","link":"#关键流程-拉镜像、启动容器、访问服务","children":[{"level":3,"title":"1. 拉取镜像","slug":"_1-拉取镜像","link":"#_1-拉取镜像","children":[]},{"level":3,"title":"2. 启动容器","slug":"_2-启动容器","link":"#_2-启动容器","children":[]},{"level":3,"title":"3. 访问页面","slug":"_3-访问页面","link":"#_3-访问页面","children":[]}]},{"level":2,"title":"进一步验证与排查","slug":"进一步验证与排查","link":"#进一步验证与排查","children":[]},{"level":2,"title":"这个练习的价值","slug":"这个练习的价值","link":"#这个练习的价值","children":[]},{"level":2,"title":"推荐的下一步","slug":"推荐的下一步","link":"#推荐的下一步","children":[]},{"level":2,"title":"常见误区","slug":"常见误区","link":"#常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/02-零基础Docker极速入门-10分钟跑起你的第一个Nginx容器.md","filePath":"docker/02-零基础Docker极速入门-10分钟跑起你的第一个Nginx容器.md"}'),n={name:"docker/02-零基础Docker极速入门-10分钟跑起你的第一个Nginx容器.md"};function h(t,i,r,d,k,c){return a(),l("div",null,[...i[0]||(i[0]=[s(`<h1 id="_02-零基础docker极速入门-10分钟跑起你的第一个nginx容器" tabindex="-1">02-零基础Docker极速入门-10分钟跑起你的第一个Nginx容器 <a class="header-anchor" href="#_02-零基础docker极速入门-10分钟跑起你的第一个nginx容器" aria-label="Permalink to “02-零基础Docker极速入门-10分钟跑起你的第一个Nginx容器”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>对初学者来说，理解 Docker 最有效的方式不是直接从复杂应用入手，而是从一个经典的“镜像拉取、容器运行、端口映射”流程开始。Nginx 作为最常见的 Web 服务，在 10 分钟内就可以帮助你把 Docker 的运行机制看清楚。</p><h2 id="为什么先从-nginx-开始" tabindex="-1">为什么先从 Nginx 开始？ <a class="header-anchor" href="#为什么先从-nginx-开始" aria-label="Permalink to “为什么先从 Nginx 开始？”">​</a></h2><p>Nginx 具备以下特点：</p><ul><li>容量小、启动快；</li><li>官方镜像已经预配置好运行环境；</li><li>服务端口固定，易于验证；</li><li>结果直观，访问即可确认是否成功。</li></ul><p>它是最适合用来建立 Docker 思维模型的“第一课”。</p><h2 id="关键流程-拉镜像、启动容器、访问服务" tabindex="-1">关键流程：拉镜像、启动容器、访问服务 <a class="header-anchor" href="#关键流程-拉镜像、启动容器、访问服务" aria-label="Permalink to “关键流程：拉镜像、启动容器、访问服务”">​</a></h2><h3 id="_1-拉取镜像" tabindex="-1">1. 拉取镜像 <a class="header-anchor" href="#_1-拉取镜像" aria-label="Permalink to “1. 拉取镜像”">​</a></h3><p>镜像可以理解为容器运行所依赖的基础模板。官方镜像已经把 Nginx 运行环境准备好了：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>这一步完成后，你会在本机的镜像仓库中得到一个名为 <code>nginx</code> 的镜像。</p><h3 id="_2-启动容器" tabindex="-1">2. 启动容器 <a class="header-anchor" href="#_2-启动容器" aria-label="Permalink to “2. 启动容器”">​</a></h3><p>接下来把镜像实例化成一个运行中的容器：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>命令含义：</p><ul><li><code>-d</code>：后台运行；</li><li><code>--name my-nginx</code>：指定容器名称，方便管理；</li><li><code>-p 8080:80</code>：将宿主机 8080 端口映射到容器内 80 端口；</li><li><code>nginx</code>：使用的镜像名称。</li></ul><h3 id="_3-访问页面" tabindex="-1">3. 访问页面 <a class="header-anchor" href="#_3-访问页面" aria-label="Permalink to “3. 访问页面”">​</a></h3><p>打开浏览器访问：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://localhost:8080</span></span></code></pre></div><p>如果出现 Nginx 默认欢迎页，说明容器已经正常运行并对外暴露服务。</p><h2 id="进一步验证与排查" tabindex="-1">进一步验证与排查 <a class="header-anchor" href="#进一步验证与排查" aria-label="Permalink to “进一步验证与排查”">​</a></h2><p>常用命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/sh</span></span></code></pre></div><ul><li><code>docker ps</code>：查看正在运行的容器；</li><li><code>docker logs</code>：查看容器日志；</li><li><code>docker exec</code>：进入容器内部查看运行环境。</li></ul><p>如果页面无法访问，先确认容器是否启动、端口是否映射、端口是否被占用。</p><h2 id="这个练习的价值" tabindex="-1">这个练习的价值 <a class="header-anchor" href="#这个练习的价值" aria-label="Permalink to “这个练习的价值”">​</a></h2><p>通过这个例子，你会把以下概念串联起来：</p><ul><li>镜像是只读模板；</li><li>容器是镜像的运行实例；</li><li>端口映射是宿主机与容器通信的桥梁；</li><li>日志和交互命令是排查故障的第一手资料。</li></ul><h2 id="推荐的下一步" tabindex="-1">推荐的下一步 <a class="header-anchor" href="#推荐的下一步" aria-label="Permalink to “推荐的下一步”">​</a></h2><p>当你把 Nginx 启动起来后，建议继续练习：</p><ul><li>停止并删除容器：<code>docker stop my-nginx &amp;&amp; docker rm my-nginx</code>；</li><li>修改 Nginx 配置并重新挂载；</li><li>结合 <code>docker-compose</code> 启动一个 Nginx + 应用程序栈。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>误以为 Docker 只是“把程序装进盒子里”。实际上它构建的是“隔离运行时环境”；</li><li>误以为容器启动就足够。没有日志和访问验证，问题往往会被忽略；</li><li>误用端口映射。<code>-p</code> 的左侧是宿主机端口，右侧是容器端口。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>10 分钟跑通 Nginx，是学 Docker 最好的起点。这个过程让你理解 Docker 的基本使用方式，也为后续学习镜像构建、数据卷、网络和编排打下基础。</p>`,36)])])}const g=e(n,[["render",h]]);export{o as __pageData,g as default};
